args.command:
cd /workspace && curl -s http://host.docker.internal:3000/assets/i18n/en.json -o loot/en.json && python3 - <<'EOF'
import json
d=json.load(open('/workspace/loot/en.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'.'+k)
    elif isinstance(o,str):
        if 'tokensale' in o.lower() or 'GIVE_US' in p or 'SECTION_ICO' in p or 'TITLE_TOKENSALE' in p:
            print(p,'=>',o[:300].replace('\n',' | '))
walk(d)
EOF
